Implementation details:
- HTML should be self-contained. We'll include JS at bottom.
- Need no dependencies.
- Use modern JS.

Let's outline JS:

```
(() => {
  'use strict';
  const ELEMENTS = {...};
  const CATEGORY = {...};
  const RECIPES = [...];
  const BASE = ['developer','ia','cafe','prompt'];
  const RECIPE_MAP = new Map();
  RECIPES.forEach(([a,b,r]) => RECIPE_MAP.set(key(a,b), r));
  const TOTAL = Object.keys(ELEMENTS).length;
  const STORAGE = 'alquimia-reactiva-v1';

  const $ = sel => document.querySelector(sel);
  const els = {...};

  let state = {
    discovered: [...BASE],
    board: [],
    sound: true,
    goalSeen: false,
    discoveryOrder: [...BASE],
  };
  let selectedId = null;
  let drag = null;
  let toastTimer, bannerTimer;
  let hintTimer;
  let audioCtx = null;

  function key(a,b){return [a,b].sort().join('|');}
  function element(id){return ELEMENTS[id];}
  function isDiscovered(id){return state.discovered.includes(id);}

  function init() {
    load();
    if (!state.board || !state.board.length) { // if no saved state: initial board
       if (!state.loaded) seedBoard();
    }
    create cards from state.board
    renderSidebar(); updateProgress(); bindEvents();
    if (!state.loaded) setTimeout(() => showToast('Arrastra <b>Developer</b> sobre <b>IA</b>...'), 900);
  }
```

