Drag:
```
function onPointerDown(e) {
  const cardEl = e.target.closest('.card');
  if (e.button !== undefined && e.button !== 0) return;
  if (cardEl) {
    const card = getCard(cardEl.dataset.cid);
    e.preventDefault();
    drag = { card, el: cardEl, startX:e.clientX, startY:e.clientY, origX:card.x, origY:card.y, moved:false, pointerId:e.pointerId };
    cardEl.setPointerCapture(e.pointerId);
    cardEl.classList.add('dragging');
    cardEl.style.zIndex = ++zTop;
    // don't set selected yet
  } else {
    clearSelection();
  }
}
function onPointerMove(e) {
 if (!drag) return;
 const dx=e.clientX-drag.startX, dy=...
 if (!drag.moved && Math.hypot(dx,dy)>5) {drag.moved=true; clearSelection();}
 if (drag.moved) {
   const rect=els.cards.getBoundingClientRect();
   let x=(e.clientX-rect.left)/rect.width;
   let y=(e.clientY-rect.top)/rect.height;
   // We want center under pointer; position card center at pointer plus offset? In Infinite Craft, card grabbed. Could maintain offset from center:
   // If pointer down not at card center, card jumps. Better store offset in normalized coords.
   const cardRect = el.getBoundingClientRect();
   const offsetX = (e.clientX - (cardRect.left + cardRect.width/2)) / boardRect.width; // initial? compute on down.
 }
}
