function attemptCombine(a,b) {
  if (!a||!b||a.cid===b.cid) return;
  const resultId = RECIPE_MAP.get(key(a.elementId,b.elementId));
  if (!resultId) { invalid(a,b); return; }
  clearSelection(); clearTargets();
  const mx=(a.x+b.x)/2, my=(a.y+b.y)/2;
  // animate consume
  a.el.classList.add('consume'); b.el.classList.add('consume');
  const resultEl = ... create immediately? 
  setTimeout(() => {
    removeCard(a.cid); removeCard(b.cid);
    const isNew = !isDiscovered(resultId);
    if (isNew) discover(resultId);
    const card = addCard(resultId, mx, my, {animate:true});
    resultEl.classList.add('combined');
    if (isNew) celebrate(resultId, card)
    else showToast(`Has combinado <b>${...}</b>...`, 'info')
    save();
  }, 160);
}
```
