const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({headless:true, executablePath:'/usr/bin/google-chrome', args:['--no-sandbox']});
  for (const viewport of [{width:1440,height:900},{width:1024,height:768},{width:768,height:1024},{width:390,height:844},{width:360,height:740}]) {
    const page = await browser.newPage({viewport});
    const errors=[];
    page.on('pageerror', e=>errors.push(e.message));
    await page.goto('file:///var/tmp/bench/ws-o9EYugK7/index.html');
    await page.waitForTimeout(350);
    const data = await page.evaluate(() => {
      const cards=[...document.querySelectorAll('.card')].map(el=>{const r=el.getBoundingClientRect(); return {text:el.innerText.replace(/\n/g,' '),x:+r.x.toFixed(0),y:+r.y.toFixed(0),w:+r.width.toFixed(0),h:+r.height.toFixed(0)}});
      const board=document.querySelector('#board').getBoundingClientRect();
      const top=document.querySelector('.topbar').getBoundingClientRect();
      const sidebar=document.querySelector('#sidebar').getBoundingClientRect();
      const footer=document.querySelector('.board-footer').getBoundingClientRect();
      const mission=document.querySelector('.mission-chip').getBoundingClientRect();
      return {cards, board:{x:board.x,y:board.y,w:board.width,h:board.height}, top:{w:top.width,h:top.height}, sidebar:{x:sidebar.x,w:sidebar.width,right:sidebar.right}, footer:{x:footer.x,y:footer.y,w:footer.width,h:footer.height}, mission:{x:mission.x,y:mission.y,w:mission.width,h:mission.height}, bodyScroll:{w:document.body.scrollWidth,h:document.body.scrollHeight}, inner:{w:innerWidth,h:innerHeight}};
    });
    console.log('\nVIEWPORT', viewport, 'errors', errors);
    console.log(JSON.stringify(data,null,1));
    await page.close();
  }
  await browser.close();
})();
EOF
