const { chromium } = require('playwright');
const FILE='file:///var/tmp/bench/ws-o9EYugK7/index.html';
const KEY='alquimia-reactiva-v1';
const BASE=['developer','ia','cafe','prompt'];
function assert(cond,msg){ if(!cond) throw new Error('ASSERT: '+msg); }
(async () => {
  const browser = await chromium.launch({headless:true, executablePath:'/usr/bin/google-chrome', args:['--no-sandbox']});
  // fresh page
  const page = await browser.newPage({viewport:{width:1200,height:800}});
  const errors=[]; page.on('pageerror',e=>errors.push(e.message)); page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
  await page.goto(FILE); await page.waitForTimeout(400);

  // sidebar add duplicate developer
  await page.locator('.mini[data-element="developer"]').click(); await page.waitForTimeout(350);
  assert(await page.locator('.card').count()===5,'add from sidebar');
  assert(await page.locator('#discoveredCount').textContent()==='4','discoveries unchanged on add');
  // select combine developer + developer via clicks
  const devs = page.locator('.card', {hasText:'Developer'});
  await devs.nth(0).click(); await page.waitForTimeout(120);
  assert(await page.locator('.card.selected').count()===1,'selection');
  await devs.nth(1).click(); await page.waitForTimeout(500);
  assert(await page.locator('.card').count()===4,'consume two, add one');
  assert(await page.locator('#discoveredCount').textContent()==='5','team discovered');
  assert((await page.locator('#bannerName').textContent())==='Equipo','banner team');

  // double click duplicate a card
  const team = page.locator('.card', {hasText:'Equipo'}).first();
  await team.dblclick(); await page.waitForTimeout(400);
  assert(await page.locator('.card').count()===5,'double click duplicate');

  // hint
  await page.locator('#hintBtn').click(); await page.waitForTimeout(200);
  assert((await page.locator('#toast').textContent()).includes('Prueba'),'hint toast');

  // reload persistence
  await page.reload(); await page.waitForTimeout(500);
  assert(await page.locator('.card').count()===5,'board persisted');
  assert(await page.locator('#discoveredCount').textContent()==='5','discoveries persisted');

  // reset
  await page.locator('#resetBtn').click(); await page.waitForTimeout(200);
  assert(await page.locator('#resetModal').isVisible(),'reset modal');
  await page.locator('#confirmReset').click(); await page.waitForTimeout(500);
  assert(await page.locator('.card').count()===4,'reset board');
  assert(await page.locator('#discoveredCount').textContent()==='4','reset discoveries');

  // search
  await page.locator('#search').fill('café'); await page.waitForTimeout(150);
  assert(await page.locator('.mini').count()===1,'search accent-insensitive');
  await page.locator('#search').fill('zzzz'); await page.waitForTimeout(100);
  assert((await page.locator('.empty-store').count())===1,'empty search');
  await page.locator('#search').fill('');

  // mobile sidebar
  const mobile = await browser.newPage({viewport:{width:390,height:844}});
  const merrors=[]; mobile.on('pageerror',e=>merrors.push(e.message));
  await mobile.goto(FILE); await mobile.waitForTimeout(300);
  assert(await mobile.locator('#panelBtn').isVisible(),'mobile panel visible');
  await mobile.locator('#panelBtn').click(); await mobile.waitForTimeout(300);
  assert(await mobile.locator('#sidebar').evaluate(el=>getComputedStyle(el).transform)!=='matrix(1, 0, 0, 1, 0, 0)','sidebar transform?');
  const sidebarBox = await mobile.locator('#sidebar').boundingBox();
  assert(sidebarBox.x < 390 && sidebarBox.x > 10,'sidebar open position');
  await mobile.locator('.mini[data-element="ia"]').click(); await mobile.waitForTimeout(350);
  assert(await mobile.locator('.card').count()===5,'mobile add from sidebar');
  const sidebarBox2 = await mobile.locator('#sidebar').boundingBox();
  assert(sidebarBox2.x >= 360,'sidebar closes after add');
  console.log('mobile sidebar after add x', sidebarBox2.x);

  // victory flow: preload state with webreactiva & mcp, board with them
  const victory = await browser.newPage({viewport:{width:1200,height:800}});
  const verrors=[]; victory.on('pageerror',e=>verrors.push(e.message));
  await victory.addInitScript(({key,base})=>{
    localStorage.setItem(key, JSON.stringify({
      v:1,
      discovered:[...base,'copiloto','codigo','modelo','agente','api','mcp','equipo','comunidad','webreactiva'],
      discoveryOrder:[...base,'copiloto','codigo','modelo','agente','api','mcp','equipo','comunidad','webreactiva'],
      board:[{elementId:'webreactiva',x:0.4,y:0.5},{elementId:'mcp',x:0.6,y:0.5}],
      sound:false, goalSeen:false
    }));
  }, {key:KEY,base:BASE});
  await victory.goto(FILE); await victory.waitForTimeout(400);
  assert(await victory.locator('.card').count()===2,'victory seed');
  const wr = await victory.locator('.card', {hasText:'Web Reactiva'}).boundingBox();
  const mcp = await victory.locator('.card', {hasText:'MCP'}).boundingBox();
  await victory.mouse.move(wr.x+wr.width/2, wr.y+wr.height/2);
  await victory.mouse.down();
  await victory.mouse.move(mcp.x+mcp.width/2, mcp.y+mcp.height/2,{steps:10});
  await victory.mouse.up();
  await victory.waitForTimeout(900);
  assert(await victory.locator('#bannerName').textContent()==='Atlas Malandriner','atlas banner');
  assert(await victory.locator('#victoryModal').isVisible(),'victory modal');
  assert(await victory.locator('#discoveredCount').textContent()==='12','count victory');
  await victory.screenshot({path:'/tmp/shot-victory.png'});
  assert(verrors.length===0,'victory errors '+verrors);

  // all elements state
  const all = await browser.newPage({viewport:{width:1200,height:800}});
  const aerrors=[]; all.on('pageerror',e=>aerrors.push(e.message));
  await all.addInitScript(({key})=>{
    const ids=['developer','ia','cafe','prompt','copiloto','codigo','spec','alucinacion','modelo','idea','equipo','hype','espresso','prompt_engineering','agente','claude_code','codex','opencode','bug','proyecto','commit','deploy','repo','issue','debug','test','eval','plan','plan_mode','sdd','open_spec','spec_kit','ai_slop','token','respuesta','charla','comunidad','cultura','webreactiva','telegram','zona','reunion','sprint','skill','skill_md','rag','contexto','agents_md','api','mcp','herramienta','multiagente','harness','loop','memoria','headroom','newsletter','podcast','masterclass','atlas','curso','premium','guia','roadmap','criterio','calambrazo','pantuflas','yak','poke','selector','revisor','llm_wiki','gbrain','wikipoke','orbit','rea','goal_oriented','odd'];
    localStorage.setItem(key, JSON.stringify({v:1,discovered:ids,discoveryOrder:ids,board:[{elementId:'developer',x:.4,y:.4},{elementId:'ia',x:.6,y:.6}],sound:false,goalSeen:true}));
  }, {key:KEY});
  await all.goto(FILE); await all.waitForTimeout(400);
  assert(await all.locator('.mini').count()===78,'all minis');
  assert(await all.locator('#discoveredCount').textContent()==='78','all count');
  assert((await all.locator('#missionText').textContent()).includes('desbloqueado'),'mission done');
  await all.locator('#hintBtn').click(); await all.waitForTimeout(200);
  assert((await all.locator('#toast').textContent()).includes('completo'),'complete hint');
  assert(aerrors.length===0,'all errors '+aerrors);

  console.log('ALL INTERACTION TESTS PASSED');
  console.log('main errors',errors,'mobile errors',merrors);
  await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
EOF
