from html.parser import HTMLParser
class P(HTMLParser):
 def __init__(self):
  super().__init__(); self.stack=[]; self.errors=[]
 def handle_starttag(self,t,a):
  if t not in ('meta','link','input','br','img','hr','source','path','rect','text','svg'): self.stack.append(t)
 def handle_startendtag(self,t,a): pass
 def handle_endtag(self,t):
  if t in ('meta','link','input','br','img','hr','source','path','rect','text','svg'): return
  if not self.stack: self.errors.append(('extra',t)); return
  if self.stack[-1]==t: self.stack.pop()
  else:
