   if t in self.stack:
    while self.stack and self.stack[-1]!=t: self.stack.pop()
    if self.stack: self.stack.pop()
p=P(); p.feed(open('index.html').read()); print('errors',p.errors[:10]); print('remaining',p.stack[-20:])
