function giveHint() {
  const available = RECIPES.filter(([a, b, result]) => isDiscovered(a) && isDiscovered(b) && !isDiscovered(result));
  if (!available.length) {
    if (state.discovered.length >= TOTAL) {
      showToast('¡Laboratorio completo! Has descubierto las ' + TOTAL + ' piezas. 🏆', 'ok', 4800);
      burst(window.innerWidth / 2, window.innerHeight / 2, 40, 1.35);
      playWin();
    } else {
      showToast('No hay pistas nuevas con lo que tienes. Sigue mezclando.', 'warn', 3200);
    }
    return;
  }

  const onBoard = (id) => state.board.some(card => card.elementId === id);
  const differentPairs = available.filter(([a, b]) => a !== b);
  const readyPairs = differentPairs.filter(([a, b]) => onBoard(a) && onBoard(b));
  let pool = readyPairs.length ? readyPairs : differentPairs;

  if (!pool.length) {
    pool = available.filter(([a, b]) => a === b && state.board.filter(card => card.elementId === a).length >= 2);
  }

  if (!pool.length) {
    const [a] = available[0];
    showToast('💡 Añade otra copia de <b>' + element(a).name + '</b> desde el almacén y mézclala consigo misma.', 'hint', 5600);
    pulseElements([a]);
    beep(740, 0.05, 0, 'sine', 0.02);
    beep(980, 0.06, 0.06, 'sine', 0.02);
    if (els.search.value.trim()) {
      els.search.value = '';
      renderSidebar();
    }
    if (window.innerWidth <= 900) openSidebar();
    return;
  }

  const pick = pool[Math.floor(Math.random() * pool.length)];
  const [a, b, result] = pick;
  showToast('💡 Prueba <b>' + element(a).name + '</b> + <b>' + element(b).name + '</b>', 'hint', 5200);
  pulseElements([a, b]);
  beep(740, 0.05, 0, 'sine', 0.02);
  beep(980, 0.06, 0.06, 'sine', 0.02);
  if (els.search.value.trim()) {
    els.search.value = '';
    renderSidebar();
  }
  if (window.innerWidth <= 900) closeSidebar();
  // La pista debe seguir siendo útil aunque el resultado sea nuevo.
  void result;
}

